    var M = {"john":{"vi":"\"Yahweh nhân từ\""},"mary":{"vi":"Không chắc chắn — \"người được yêu\", \"vị đắng\", hoặc \"đứa con mong ước\""},"muhammad":{"vi":"\"Người được ca ngợi\", \"đáng ca ngợi\""},"alexander":{"vi":"\"Người bảo vệ con người\" (aléxō \"bảo vệ\" + anḗr \"người\")"},"joseph":{"vi":"\"Ngài sẽ thêm vào\" / \"cầu Chúa ban thêm\""},"michael":{"vi":"\"Ai giống như Thiên Chúa?\""},"george":{"vi":"\"Nông dân, người cày ruộng\" (gē \"đất\" + ergon \"công việc\")"},"sophia":{"vi":"\"Sự khôn ngoan\""},"fatima":{"vi":"\"Người cai sữa / kiêng khem\" (gốc từ f-ṭ-m)"},"ali":{"vi":"\"Cao cả, tôn quý, siêu phàm\" (gốc từ ʿ-l-w)"},"krishna":{"vi":"\"Tối, đen\" (chỉ nước da xanh đen của vị thần)"},"rama":{"vi":"\"Dễ chịu, quyến rũ, vui thích\" (gốc từ ram- \"làm vui lòng\")"},"david":{"vi":"\"Người được yêu dấu\""},"daniel":{"vi":"\"Thiên Chúa là đấng phán xét của tôi\" (dān \"phán xét\" + ʼēl \"Thiên Chúa\")"},"peter":{"vi":"\"Đá tảng, hòn đá\" — do Chúa Giêsu đặt để dịch tiếng Aram Kēfā"},"paul":{"vi":"\"Nhỏ bé, khiêm nhường\""},"thomas":{"vi":"\"Sinh đôi\""},"abraham":{"vi":"“Cha của nhiều dân tộc”"},"isaac":{"vi":"“Người ấy cười” / “người ấy sẽ cười”"},"jacob":{"vi":"“Kẻ chiếm chỗ”, “người nắm gót chân”"},"moses":{"vi":"“Được vớt lên từ nước” (theo truyền thống)"},"solomon":{"vi":"“Hòa bình” (từ shalom)"},"matthew":{"vi":"“Quà tặng của Yahweh”"},"adam":{"vi":"“Con người; nhân loại”, từ adamah “đất, mặt đất”"},"noah":{"vi":"“Nghỉ ngơi, an ủi”"},"gabriel":{"vi":"“Chúa là sức mạnh của tôi”"},"elijah":{"vi":"“Đức Chúa của tôi là Yahweh”"},"sarah":{"vi":"“Công chúa, quý bà”"},"anna":{"vi":"“Ân điển, ơn huệ”"},"elizabeth":{"vi":"“Đức Chúa của tôi là lời thề”"},"omar":{"vi":"“Trường thọ, hưng thịnh, phồn vinh”"},"aisha":{"vi":"“Sống, sống động, thịnh vượng”"},"khadija":{"vi":"“Sinh sớm, đứa trẻ sinh non”"},"abdullah":{"vi":"“Tôi tớ của Thượng Đế”"},"hassan":{"vi":"\"Tốt lành, đẹp trai, xinh đẹp\""},"husayn":{"vi":"\"Hasan bé nhỏ\", \"người đẹp nhỏ bé\""},"zaynab":{"vi":"Một loài cây sa mạc có hoa thơm ngát"},"nicholas":{"vi":"\"Chiến thắng của nhân dân\""},"helen":{"vi":"Không chắc chắn — có lẽ là \"ngọn đuốc, người rạng rỡ\""},"catherine":{"vi":"Không chắc chắn — theo từ nguyên dân gian gắn với \"thuần khiết\""},"margaret":{"vi":"\"Ngọc trai\""},"philip":{"vi":"\"Người yêu ngựa\""},"theodore":{"vi":"\"Món quà của Chúa\""},"anthony":{"vi":"Một tên thị tộc La Mã có nguồn gốc không rõ, có thể từ tiếng Etrusca"},"julia":{"vi":"\"Trẻ trung\"; dạng giống cái của tên thị tộc Iulius, liên hệ với thần Jupiter"},"lakshmi":{"vi":"\"Dấu hiệu, ký hiệu\" → \"may mắn, thịnh vượng\""},"arjun":{"vi":"\"Sáng, trắng, bạc, trong trẻo\""},"sita":{"vi":"\"Luống cày\" (đường do lưỡi cày rạch)"},"ganesh":{"vi":"\"Chúa tể của các gana (đoàn tùy tùng, binh chúng)\""},"priya":{"vi":"\"Yêu dấu, thân thương\""}};
    var B = {"john":{"vi":"Một trong những cái tên phổ biến nhất trên Trái Đất. Tên Hebrew Yōḥānān, được mang bởi John the Baptist và John the Apostle, đi vào tiếng Hy Lạp thành Iōánnēs và tiếng Latinh thành Iohannes, rồi lan khắp thế giới Kitô giáo. Tây Âu giữ lại phụ âm đầu J/G (John, Jean, Juan, Giovanni); thế giới Đông Slav biến đổi nó thành Ivan; còn Qurʼan lưu giữ một dạng Ả Rập song song, Yaḥyā, cho cùng vị tiên tri ấy."},"mary":{"vi":"Tên của mẹ Chúa Giêsu và của Miriam, chị của Moses, và qua họ trở thành một trong những tên nữ được tôn kính nhất thế giới. Tiếng Hy Lạp Maria và tiếng Latinh Maria đã đưa nó vào mọi ngôn ngữ Kitô giáo; Qurʼan gọi là Maryam, người phụ nữ duy nhất được nêu tên trong đó, nên cái tên này cũng trọng yếu không kém trong thế giới Hồi giáo."},"muhammad":{"vi":"Tên của vị Tiên tri của Hồi giáo, và theo nhiều thống kê là tên nam giới phổ biến nhất trên Trái Đất. Từ tiếng Ả Rập muḥammad (gốc ḥ-m-d, “ca ngợi”), nó theo Hồi giáo đi vào mọi ngôn ngữ của thế giới Hồi giáo, mỗi nơi lại biến đổi âm thanh: Mehmet trong tiếng Thổ Nhĩ Kỳ, Mohammad trong tiếng Ba Tư/Urdu, Muhamed ở Bosnia, Mamadou ở Tây Phi, Muhammad/Mohd ở Đông Nam Á."},"alexander":{"vi":"Được Alexander Đại đế mang qua ba lục địa, với những cuộc chinh phục gieo cái tên này từ Hy Lạp đến Ấn Độ. Về sau Kitô giáo lan truyền nó xa hơn qua các vị thánh và giáo hoàng. Hầu như ở đâu nó cũng được rút gọn một cách trìu mến — Alex, Sasha, Sander, Xander, Ale, Iskandar — và thậm chí đi vào thế giới Hồi giáo dưới dạng Iskandar/Sikandar."},"joseph":{"vi":"Tên của tổ phụ Joseph, người bị bán sang Ai Cập, và của Thánh Joseph, chồng của Mary. Tiếng Hebrew Yōsēf đi qua tiếng Hy Lạp Iōsḗph và Latinh Ioseph vào mọi ngôn ngữ Kitô giáo, rút gọn thành José ở bán đảo Iberia, Giuseppe ở Ý và Josef trong thế giới Đức và Slav. Qurʼan kể câu chuyện của cùng vị tổ phụ ấy dưới dạng Ả Rập song song Yūsuf, vốn lan theo Hồi giáo từ Tây Phi đến Indonesia."},"michael":{"vi":"Ban đầu là tên của tổng lãnh thiên thần Michael, vị chỉ huy chiến binh của thiên binh, và sự sùng kính dành cho ngài đã đưa cái tên này lan khắp thế giới Kitô giáo. Tiếng Hy Lạp Michaḗl và tiếng Latinh Michael phân nhánh thành Michel, Miguel, Michele, Michael và Mikhail trong tiếng Slav, làm mềm âm họng ḵ của tiếng Hebrew thành âm k hoặc h dọc đường. Kinh Qurʼan gọi cùng vị thiên thần ấy là Mīkāʼīl, tạo nên một dạng Hồi giáo song song được dùng từ Iran đến Tây Phi."},"george":{"vi":"Từ tiếng Hy Lạp Geōrgios, dựng trên geōrgós “nông dân, người cày cấy đất”, cái tên có tầm lan tỏa rộng lớn là nhờ Saint George, vị tử đạo giết rồng được tôn kính khắp thế giới Kitô giáo và là thánh bổn mạng của Anh, Gruzia và Ethiopia. Nó tỏa ra thành Jorge, Giorgio, Georg và Jerzy, còn thế giới Đông Slav thì tách nó thành hai cái tên cùng tồn tại — Georgy bác học và Yuri đời thường. Ở vùng Kavkaz, đây là cái tên được cả nước ưa chuộng: Giorgi trong tiếng Gruzia và Gevorg trong tiếng Armenia."},"sophia":{"vi":"Trong tiếng Hy Lạp, sophía đơn giản có nghĩa là “trí tuệ”, được nhân cách hóa như một đức hạnh và được tôn thờ trong đại thánh đường Hagia Sophia, “Trí Tuệ Thánh Thiêng”, ở Constantinople. Được lưu truyền qua truyền thống Byzantine và Chính Thống giáo, mang bởi các hoàng hậu và các vị thánh, cái tên lan ra thành Sofia, Sophie, Zsófia và Zofia. Ngày nay nó là một trong những tên bé gái phổ biến nhất thế giới, đứng đầu bảng khai sinh khắp châu Âu và châu Mỹ; tiếng Nga cho nó dạng gọi thân mật Sonya."},"fatima":{"vi":"Là tên của Fāṭima al-Zahrāʼ, con gái của Nhà tiên tri Muhammad và vợ của ʿAlī, và do đó là một trong những tên nữ được tôn kính nhất trong Hồi giáo — nhất là trong truyền thống Shia, nơi bà là mẹ của các imam. Từ gốc Ả Rập f-ṭ-m (“cai sữa”), cái tên lan đi cùng Hồi giáo và mềm đi dọc đường: tiếng Thổ Nhĩ Kỳ rút gọn thành Fatma, tiếng Ba Tư tròn hóa phần đuôi thành Fāṭeme, còn Nam Á và Đông Nam Á giữ dạng đầy đủ hơn Fatimah. Ở vùng Balkan, nó tồn tại dưới dạng Fatima cùng tên gọi thân mật Fata."},"ali":{"vi":"Là tên của ʿAlī ibn Abī Ṭālib, em họ và con rể của Nhà tiên tri Muhammad, vị caliph thứ tư trong truyền thống Sunni và vị imam đầu tiên của Hồi giáo Shia — điều khiến Ali trở thành một trong những cái tên trung tâm của thế giới Hồi giáo, và cũng là một trong những “danh xưng tốt đẹp”, bởi al-ʿAlī là một thuộc tính của Thượng Đế. Từ tiếng Ả Rập ʿAlī (gốc ʿ-l-w, “cao cả”), âm thanh của nó truyền qua các ngôn ngữ gần như không đổi: Ali trong tiếng Thổ Nhĩ Kỳ và Ba Tư, Ali trong tiếng Urdu, Alija trong tiếng Bosnia, Aliyu ở Tây Phi. Ở phương Tây, nó được biết đến nhiều nhất qua võ sĩ quyền anh Muhammad Ali."},"krishna":{"vi":"Krishna là hóa thân thứ tám của Vishnu và là một trong những vị thần được yêu mến nhất của Ấn Độ giáo — chàng mục đồng thổi sáo ở Vrindavan và bậc hiền triết đánh xe trong Bhagavad Gita. Từ kṛṣṇa trong tiếng Phạn nghĩa đen là \"sẫm, đen\", tả nước da của ngài, và sinh ra những biến thể trìu mến như Kanha và Kannan trong tiếng Tamil. Là một tên riêng, nó phổ biến khắp Ấn Độ và toàn bộ cộng đồng Ấn giáo hải ngoại; sự lan tỏa ở Đông Nam Á đi qua nghệ thuật múa rối bóng wayang và sử thi Mahabharata."},"rama":{"vi":"Rama là một hóa thân của Vishnu và là người anh hùng của sử thi Ramayana, vị vua lý tưởng của Ayodhya mà câu chuyện được kể lại vào hàng nhiều nhất thế giới. Từ rāma trong tiếng Phạn nghĩa là \"vui lòng, quyến rũ\". Trên hết, chính bản sử thi này đã mang cái tên ấy đi khắp Đông Nam Á: các vị vua Thái thuộc vương triều Chakri đều lấy vương hiệu là Rama, chính kinh đô Ayutthaya được đặt theo Ayodhya nơi Rama sinh ra, và Rama vẫn sống mãi trong Reamker của Campuchia (với tên Preah Ream), trong nghệ thuật wayang của Java và Bali, cùng Phra Lak Phra Ram của Lào."},"david":{"vi":"Tên của vị vua chăn cừu của Israel, ông vua thứ hai và người hạ gục Goliath, được tôn kính như nhau trong Do Thái giáo, Kitô giáo và Hồi giáo. Chữ Dāwīḏ trong tiếng Hebrew đi qua tiếng Hy Lạp và tiếng Latinh vào mọi ngôn ngữ châu Âu gần như không đổi, trong khi Davit của Gruzia và Dawit của Ethiopia trở thành tên hoàng gia theo cách riêng của chúng. Vì David cũng là một nhà tiên tri trong kinh Qurʼan, một nhánh Hồi giáo song song chạy qua chữ Dāwūd trong tiếng Ả Rập — Daud, Davut, Daudi — khắp thế giới Hồi giáo."},"daniel":{"vi":"Bắt nguồn từ vị tiên tri thấu thị trong Sách Daniel, mà đức tin trong hang sư tử đã khiến cái tên trở thành biểu tượng của lòng kiên định. Chữ Dāniyyēl trong tiếng Hebrew đi qua tiếng Hy Lạp Daniḗl và tiếng Latinh Daniel vào phương Tây Kitô giáo, giữ lối viết ổn định một cách đáng kinh ngạc, trong khi thế giới Slav nhào nặn nó thành Daniil và Danylo. Daniel cũng được tôn kính trong truyền thống Hồi giáo với danh nhà tiên tri Dāniyāl, mà lăng mộ ở Susa đến nay vẫn là nơi hành hương."},"peter":{"vi":"Cái tên Chúa Giêsu ban cho người đánh cá Simon — tiếng Hy Lạp Pétros, \"tảng đá\", là bản dịch của biệt danh Aram Kēfā — khiến ông trở thành tảng đá mà trên đó Giáo hội được xây dựng. Là vị giáo hoàng đầu tiên, Thánh Phêrô mang cái tên này đến mọi vùng đất Kitô giáo: Latinh Petrus, Pháp Pierre, Tây Ban Nha Pedro, Ý Pietro, Nga Pyotr. Kitô hữu phương Đông giữ dạng Hy Lạp Petros, còn Kitô hữu nói tiếng Ả Rập gọi là Buṭrus."},"paul":{"vi":"Tên họ La Mã Paulus, nghĩa là “nhỏ bé”, được Tông đồ Paul — vốn tên là Saul thành Tarsus — mang lấy; những lá thư của ông đã định hình nền thần học Kitô giáo và đưa tên ông đi khắp thế giới. Các giáo hội nói tiếng Hy Lạp gọi ông là Paûlos, và từ Paulus trong tiếng Latinh đã sinh ra Pablo, Paolo, Paulo, Paweł cùng Pavel trong các ngôn ngữ Slav. Tiếng Armenia biến đổi nó một cách ấn tượng thành Poġos, còn các Kitô hữu nói tiếng Ả Rập gọi ông là Būlus."},"thomas":{"vi":"Biệt danh của vị tông đồ từng hoài nghi sự Phục Sinh cho đến khi chạm vào các vết thương của Chúa Kitô — tiếng Aram Tʼōmā, nghĩa là “sinh đôi”, mà các sách Phúc Âm tiếng Hy Lạp cũng dịch là Dídymos. Qua Thōmâs trong tiếng Hy Lạp và Thomas trong tiếng Latinh, nó lan sang phương Tây thành Thomas, Tomás, Tommaso và Tomasz, trong khi phương Đông Slav biến đổi nó thành Foma và Khoma. Các Kitô hữu nói tiếng Ả Rập gìn giữ âm Aram dưới dạng Tūmā."},"abraham":{"vi":"Vị tổ phụ được tôn kính là cha của những người có đức tin trong cả ba tôn giáo Abraham. Tên Hebrew Avraham, “cha của muôn dân”, đi qua Abraám trong tiếng Hy Lạp và Abraham trong tiếng Latinh vào phương Tây Kitô giáo, trong khi kinh Qurʼan nêu dạng song hành Ibrāhīm — một trong những tên nam giới phổ biến nhất khắp thế giới Hồi giáo, từ Maroc đến Indonesia. Tiếng Hà Lan rút gọn thành Bram; vùng Kavkaz biến đổi thành Ibragim."},"isaac":{"vi":"Con trai của Abraham và là vị tổ phụ thứ hai, tên Hebrew của ông là Yitzḥaq nghĩa là “ông ấy cười.” Isaák trong tiếng Hy Lạp và Isaac trong tiếng Latinh đưa nó sang phương Tây — Isacco trong tiếng Ý, Isaak trong tiếng Đức và tiếng Nga — trong khi kinh Qurʼan gọi cùng vị tiên tri ấy là Isḥāq. Là cái tên được yêu chuộng trong các gia đình Do Thái, Kitô giáo lẫn Hồi giáo, nó đã được mang bởi những nhân vật từ Isaac Newton đến nhà văn Nga Isaak Babel."},"jacob":{"vi":"Vị tổ phụ thứ ba, về sau được đổi tên thành Israel; tên Hebrew của ông, Yaʿaqov, đã sinh ra một trong những cây phả hệ rối rắm nhất trong toàn bộ ngành danh xưng học. Iacobus trong tiếng Latinh cho ra Jacob, Jakob và Yakov trong các ngôn ngữ Slav, nhưng một biến thể Latinh bình dân Iacomus lại tách ra thành Giacomo trong tiếng Ý, Jacques trong tiếng Pháp, James trong tiếng Anh, cùng Diego, Santiago, Tiago và Jaime của bán đảo Iberia — tất cả đều là những dạng song trùng của cùng một cái tên. Kinh Qurʼan lưu giữ vị tiên tri này là Yaʻqūb."},"moses":{"vi":"Vị tiên tri đã dẫn dân Israel ra khỏi Ai Cập; tên Hebrew của ông, Mosheh, theo truyền thống được giải nghĩa là \"người được vớt lên từ nước.\" Qua tiếng Hy Lạp Mōÿsês và tiếng Latinh Moyses, tên này lan rộng thành Moses, tiếng Pháp Moïse, tiếng Tây Ban Nha Moisés và tiếng Ý Mosè; trong khi Mūsā — cái tên được nhắc đến trong kinh Qurʼan nhiều hơn bất kỳ vị tiên tri nào khác — đã trở thành một trong những cái tên lớn của thế giới Hồi giáo, được hoàng đế Mansa Musa của đế quốc Mali mang."},"solomon":{"vi":"Vị vua khôn ngoan, con trai của David; tên Hebrew của ông, Shlomoh, bắt nguồn từ shalom, nghĩa là \"hòa bình.\" Qua tiếng Hy Lạp Solomṓn và tiếng Latinh Salomon, tên này thành Solomon, tiếng Pháp Salomon, tiếng Ý Salomone và tiếng Bồ Đào Nha Salomão. Các hoàng đế Ethiopia tự nhận là hậu duệ của ông qua vương triều Solomon, còn kinh Qurʼan tôn kính ông là vị vua-tiên tri Sulaymān — cội nguồn của tên Thổ Nhĩ Kỳ Süleyman, được vị vua vĩ đại nhất của các sultan Ottoman mang."},"matthew":{"vi":"Tên của sứ đồ và thánh sử Matthew, người thu thuế được Chúa Giêsu kêu gọi và theo truyền thống là tác giả sách Phúc Âm thứ nhất. Tiếng Hebrew Mattityāhū (\"món quà của Yahweh\") được rút gọn trong tiếng Hy Lạp thành Maththaîos và Latinh hóa thành Matthaeus, rồi lan khắp thế giới Kitô giáo dưới các dạng Matteo, Mateo, Matthieu, Mateusz và Matvei trong các ngôn ngữ Slav. Các tín hữu Kitô nói tiếng Ả Rập gọi vị thánh sử là Mattā."},"adam":{"vi":"Tên của người đàn ông đầu tiên, được nặn từ đất trong sách Sáng Thế và được nhắc đến hai mươi lăm lần trong kinh Qurʼan, nên được người Do Thái, Kitô hữu và người Hồi giáo cùng chia sẻ. Điều khác thường là cái tên này hầu như không cần biến đổi khi chuyển từ ngôn ngữ này sang ngôn ngữ khác — Adam trong tiếng Anh, Đức, Ba Lan và Ả Rập, Adán trong tiếng Tây Ban Nha, Adamo trong tiếng Ý, Adem trong tiếng Thổ Nhĩ Kỳ và tiếng Bosnia, Adamu trong tiếng Hausa và Swahili. Trong thế giới Hồi giáo, Ādam là một tên gọi hằng ngày rất phổ biến."},"noah":{"vi":"Người đóng con tàu và sống sót qua trận Đại Hồng Thủy, được tôn kính trong cả Kinh Thánh lẫn kinh Qurʼan. Tiếng Hebrew Nōaḥ qua tiếng Hy Lạp Nôe và Latinh Noe trở thành Noé trong các ngôn ngữ Rôman và Noè trong tiếng Ý, còn tiếng Anh giữ dạng đầy đủ hơn là Noah. Sang thế kỷ hai mươi mốt, Noah đã vọt lên đứng đầu bảng tên bé trai khắp Hoa Kỳ và châu Âu, và thậm chí được vay mượn trở lại vào Nhật Bản dưới dạng tên hiện đại Noa. Kinh Qurʼan kể cùng câu chuyện ấy dưới dạng Ả Rập song hành Nūḥ, một trong năm vị đại tiên tri của Hồi giáo."},"gabriel":{"vi":"Tên của vị tổng lãnh thiên thần đã mặc khải các thị kiến cho Daniel, báo tin về sự ra đời của John và Jesus, và trong Hồi giáo đọc Kinh Qurʼan cho Muhammad. Từ tiếng Hebrew Gaḇrīʼēl, tên này trở thành Gabriḗl trong tiếng Hy Lạp và Gabriel trong tiếng Latinh, giữ gần với gốc trong tiếng Pháp, Tây Ban Nha, Bồ Đào Nha và Đức, mềm đi thành Gabriele trong tiếng Ý và Gavriil / Gavrilo trong các ngôn ngữ Slav. Kinh Qurʼan gọi cùng vị thiên thần ấy là Jibrīl, và ở Ethiopia, tổng lãnh thiên thần Gabrʼel được tôn kính sâu sắc."},"elijah":{"vi":"Tên của vị tiên tri nảy lửa sống vào thế kỷ 9 TCN, người đã đối đầu với các tư tế của Baal trên núi Carmel và được cất lên trời trong một cơn gió lốc. Trong tiếng Hy Lạp của Tân Ước, ông là Ēlías, hình thức đã sinh ra Elias trong tiếng Latinh cùng nhiều dạng châu Âu Elias / Élie / Ilie, còn thế giới Đông Slav biến ông thành Ilya thường ngày. Dạng đầy đủ hơn Elijah đã trở thành một cái tên hàng đầu trong tiếng Anh hiện đại. Kinh Qurʼan tôn kính cùng vị tiên tri ấy dưới dạng Ả Rập song hành Ilyās."},"sarah":{"vi":"Tên của người vợ của tổ phụ Abraham, người trong sách Sáng Thế được đổi tên từ Sarai thành Sarah, nghĩa là \"công chúa\". Sárra trong tiếng Hy Lạp và Sara trong tiếng Latinh đã đưa nó đi khắp thế giới Kitô giáo, nơi nó trở thành một trong những cái tên nữ được ưa chuộng nhất của thời hiện đại. Vì Abraham là vị tổ phụ chung, cùng cái tên ấy tiếp tục sống trong thế giới Hồi giáo dưới dạng Sāra, và biến đổi trìu mến từ Zara đến Saara trong tiếng Phần Lan."},"anna":{"vi":"Bắt nguồn từ tiếng Hebrew Ḥannāh, mẹ của tiên tri Samuel, tên có nghĩa là \"ân sủng\". Tiếng Hy Lạp chuyển thành Ánna — mang bởi nữ tiên tri Anna trong Phúc âm Luca — và qua tiếng Latinh trở thành một trong những cái tên nữ phổ biến nhất châu Âu, càng được tôn kính như tên của Thánh Anne, mẹ của Đức Trinh Nữ Mary. Tiếng Anh giữ cả Anna gốc Hy Lạp lẫn Hannah phục nguyên từ Hebrew như một cặp song hình, và cùng nhân vật ấy xuất hiện trong Hồi giáo là Ḥanna, mẹ của Mary."},"elizabeth":{"vi":"Bắt nguồn từ tiếng Hebrew Elišévaʿ, vợ của Aaron và, trong Phúc âm Luca, mẹ của John the Baptist. Elisábet trong tiếng Hy Lạp và Elisabeth trong tiếng Latinh đã truyền bá nó khắp thế giới Kitô giáo, nơi nó được mang bởi các vị thánh và một chuỗi dài các nữ hoàng, trên hết là Elizabeth I và Elizabeth II của Anh. Ở bán đảo Iberia, cùng cái tên ấy được tái tạo thành một nhánh nổi tiếng, Isabel (tiếng Ý Isabella), trong khi thế giới Slav và Hungary cho nó dạng Yelizaveta và Erzsébet."},"omar":{"vi":"Là tên của ʿUmar ibn al-Khattāb, một môn đồ của Nhà tiên tri và vị caliph Rāshidūn thứ hai, người có triều đại định hình nên nhà nước Hồi giáo sơ khai; ʿUmar là một trong những tên nam giới kinh điển của thế giới Hồi giáo. Bắt nguồn từ gốc từ tiếng Ả Rập ʿ-m-r (“sống, hưng thịnh”), nó có nghĩa là “trường thọ, thịnh vượng”. Tên này biến đổi thành Ömer trong tiếng Thổ Nhĩ Kỳ và Omer trong tiếng Bosnia, rồi đến với phương Tây qua những người như Omar Sharif. Một cái tên Hebrew không liên quan là Omar — cháu của Esau trong sách Sáng thế — chỉ là sự trùng hợp về âm."},"aisha":{"vi":"Là tên của ʿĀʼisha bint Abī Bakr, một người vợ của Nhà tiên tri Muhammad, nổi tiếng là học giả và người thuật lại hadith, điều đã khiến nó trở thành một trong những tên nữ giới phổ biến nhất trên khắp thế giới Hồi giáo. Bắt nguồn từ gốc từ tiếng Ả Rập ʿ-y-sh (“sống”), nó có nghĩa là “đang sống, còn sống”. Tiếng Thổ Nhĩ Kỳ biến nó thành Ayşe — từ lâu là tên nữ phổ biến nhất ở Thổ Nhĩ Kỳ — trong khi vùng Maghreb dùng Aïcha và Nam Á dùng Ayesha. Trong những thập niên gần đây, nó cũng được ưa chuộng rộng rãi ở Anh, Pháp và Hoa Kỳ."},"khadija":{"vi":"Khadīja bint Khuwaylid là người vợ đầu tiên của Nhà tiên tri Muhammad, một thương nhân giàu có ở Mecca và là người đầu tiên chấp nhận Hồi giáo; kể từ đó tên bà luôn được trân trọng. Nó bắt nguồn từ gốc từ tiếng Ả Rập kh-d-j, gắn với đứa trẻ “sinh sớm” hoặc sinh non. Tiếng Thổ Nhĩ Kỳ mang hình thức Hatice, Tây Phi có Hadiza trong tiếng Hausa và Khady ở Senegal, còn tiếng Swahili là Hadija. Cùng với Fatima và Aisha, nó nằm trong số những tên nữ giới phổ biến nhất của thế giới Hồi giáo."},"abdullah":{"vi":"Một cái tên thần thánh (theophoric) mang nghĩa “tôi tớ của Thượng đế”, ghép từ ʿabd (“tôi tớ”) và Allāh. Đó là tên cha của Nhà tiên tri Muhammad, ʿAbd Allāh ibn ʿAbd al-Muttalib, và một hadith nêu ʿAbdullāh cùng ʿAbd al-Rahmān là những cái tên được Thượng đế yêu mến nhất — nên nó nằm trong số những cái tên được khuyến khích nhất trong Hồi giáo. Nó trải khắp thế giới Hồi giáo với chỉ đôi chút biến âm: Abdollah trong tiếng Ba Tư, Abdallah và Abdellah ở Maghreb, Abdullahi ở Nigeria, Abdoulaye ở Tây Phi nói tiếng Pháp, và Abdulah ở Bosnia."},"hassan":{"vi":"Ḥasan (gốc từ ḥ-s-n, “tốt đẹp, xinh đẹp”) là tên của Hasan ibn Ali, cháu ngoại lớn của Nhà tiên tri Muhammad và là Imam Shia thứ hai. Nó gần như luôn đi cặp với tên người em — Hasan và Husayn cùng nhau. Được Hồi giáo mang đi khắp thế giới, nó giữ một hình thức ổn định đáng kể (Hasan trong tiếng Thổ Nhĩ Kỳ, Hasan/Haso trong tiếng Bosnia) và vẫn là một trong những tên nam giới phổ biến nhất trong thế giới Hồi giáo."},"husayn":{"vi":"Ḥusayn là dạng thu nhỏ của Ḥasan — “Hasan bé nhỏ”, “người xinh đẹp nhỏ bé”. Đây là tên của Husayn ibn Ali, cháu ngoại nhỏ tuổi hơn của Nhà Tiên tri; sự tuẫn đạo của ông trong trận Karbala năm 680 CN đã biến cái tên này thành trái tim tình cảm của Hồi giáo Shia, được tưởng niệm hằng năm vào lễ Ashura. Các biến thể của nó lan khắp thế giới Hồi giáo: Hossein trong tiếng Ba Tư, Hüseyin trong tiếng Thổ Nhĩ Kỳ, Hussain ở Nam Á, và Hussein trong tiếng Ả Rập mà Saddam Hussein cùng Quốc vương Hussein của Jordan từng mang."},"zaynab":{"vi":"Zaynab là tên của một loài cây sa mạc thơm ngát, trổ hoa. Cái tên này được mang bởi một người con gái của Nhà Tiên tri Muhammad, Zaynab bint Muhammad, và bởi cháu gái của ông, Zaynab bint Ali, em gái của Husayn và một nữ anh hùng được tôn kính trong thảm kịch Karbala. Cái tên nở rộ khắp thế giới Hồi giáo, trên hết là dưới dạng Zeynep trong tiếng Thổ Nhĩ Kỳ — suốt nhiều năm là tên con gái phổ biến nhất ở Thổ Nhĩ Kỳ — và dưới dạng Zenabou ở Tây Phi."},"nicholas":{"vi":"Bắt nguồn từ tiếng Hy Lạp Nikólaos, \"chiến thắng của nhân dân\", được lan truyền khắp Kitô giáo qua sự sùng kính Thánh Nicholas thành Myra — vị giám mục thế kỷ 4 mà truyền thuyết tặng quà đã sinh ra Santa Claus, bản thân cái tên này cũng mòn dần từ Sinterklaas trong tiếng Hà Lan. Hầu như ở đâu nó cũng được rút gọn một cách trìu mến: Klaus trong tiếng Đức, Klaas trong tiếng Hà Lan, Nikos trong tiếng Hy Lạp, Kolya trong tiếng Nga. Đông Âu nhào nặn nó thành Nikolai, Mykola và Mikuláš, còn Hungary biến nó thành Miklós."},"helen":{"vi":"Dạng tiếng Anh của Helénē trong tiếng Hy Lạp, có lẽ bắt nguồn từ một từ nghĩa là \"ngọn đuốc\" hay \"người rạng rỡ\". Cái tên được mang bởi Helen thành Troy, người mà sắc đẹp được cho là đã \"khiến nghìn con thuyền ra khơi\", và bởi Thánh Helena, mẹ của hoàng đế Constantine, người được cho là đã tìm ra Thánh Giá Thật. Qua tiếng Latinh Helena, nó trở thành Elena khắp thế giới Rôman và Nam Slav, và Yelena / Olena ở phương Đông, còn tiếng Hungary nhào nặn nó thành Ilona."},"catherine":{"vi":"Bắt nguồn từ tiếng Hy Lạp Aikaterínē, sớm được từ nguyên dân gian gắn với katharós, \"thanh khiết\", điều đã cố định cách viết -th- ở phương Tây. Được lan truyền nhờ sự sùng kính vô cùng phổ biến dành cho Thánh Catherine thành Alexandria, nó trở thành một trong những tên nữ được dùng nhiều nhất châu Âu, được các nữ hoàng và hoàng hậu mang, từ Catherine de Medici đến Catherine the Great. Nó rút gọn thành cả một tủ tên gọi thân mật — Kate, Katie, Katya, Kasia — một trong số đó, Karin của tiếng Đức và tiếng Thụy Điển, đồng âm với một tên con gái Nhật."},"margaret":{"vi":"Bắt nguồn từ tiếng Hy Lạp margarítēs (\"ngọc trai\"), một từ mà chính tiếng Hy Lạp cũng mượn từ phương đông xa hơn. Sự sùng kính Thánh Margaret thành Antioch khiến cái tên được ưa chuộng khắp châu Âu thời trung cổ, về sau được nhiều nữ hoàng mang, và từ Margaret Thatcher đến Margaret Atwood. Các dạng tên thân mật cũng có đời sống riêng — Greta trong tiếng Đức, Rita trong tiếng Ý và tiếng Tây Ban Nha, và Daisy trong tiếng Anh, bởi từ marguerite trong tiếng Pháp về sau chỉ loài hoa cúc."},"philip":{"vi":"Bắt nguồn từ tiếng Hy Lạp Phílippos (\"người yêu ngựa\"), một cái tên của hoàng gia Macedonia mà Philip II, cha của Alexander Đại đế, mang. Là tên của một tông đồ, nó lan khắp thế giới Cơ Đốc, và trở thành cái tên được các vua vùng Iberia ưa chuộng — sáu vị Felipe của Tây Ban Nha và vài vị Filipe của Bồ Đào Nha, mà quần đảo Philippines được đặt tên theo họ. Người Anh biết đến nó rõ nhất qua Prince Philip, cố Công tước xứ Edinburgh."},"theodore":{"vi":"Bắt nguồn từ tiếng Hy Lạp Theódōros (\"món quà của Chúa\"), một hình ảnh đảo ngược của Dorothea. Được nhiều vị thánh thời sơ khai mang, nó bén rễ khắp châu Âu và xa hơn — Fyodor trong tiếng Nga của Dostoevsky và Tewodros của Ethiopia. Trong tiếng Anh, nó duyên dáng qua các dạng gọi thân mật Ted, Teddy và Theo."},"anthony":{"vi":"Bắt nguồn từ tên thị tộc La Mã Antōnius, một gens cổ có thể gốc Etrusca, mà thành viên tai tiếng nhất là Mark Antony (Marcus Antōnius). Nhiều vị thánh mang tên Anthony — trên hết là Anthony Cả và Anthony thành Padua — đã đưa nó lan khắp thế giới Cơ Đốc, nơi Antonio trở thành một trong những cái tên phổ biến nhất của Ý và vùng Iberia. Cách viết có chữ h phản ánh mối liên hệ nhầm lẫn về sau với tiếng Hy Lạp ánthos (\"hoa\")."},"julia":{"vi":"Dạng giống cái của tên thị tộc La Mã Iūlius, gia tộc của Julius Caesar và hoàng đế Augustus, điều khiến Iūlia trở thành một trong những cái tên lớn của vương triều Julio-Claudius — cả con gái của Caesar lẫn con gái của Augustus đều tên Julia. Vốn cũng là tên một nữ thánh Cơ Đốc từ lâu, ngày nay nó là một trong những cái tên con gái được ưa chuộng nhất khắp châu Âu và châu Mỹ. Dạng giống đực của nó vẫn tồn tại là Julius, Julio và Jules."},"lakshmi":{"vi":"Lakshmi là nữ thần Hindu của cải, may mắn và sắc đẹp, đồng thời là phối ngẫu của Vishnu, hiện ra bên mỗi hóa thân của ngài dưới một hình dạng tương xứng. Từ tiếng Phạn lakṣmī bắt nguồn từ lakṣ nghĩa là “đánh dấu, nhận biết”, gợi ý về một điềm lành và, mở rộng ra, sự thịnh vượng. Bà được tôn thờ hơn cả trong dịp lễ Diwali, và tên bà là một trong những tên nữ phổ biến nhất khắp Nam Ấn — dù các tên ghép như Lakshmi Narayan và các họ như Mittal cũng mang tên này cho nam giới. Ở Bengal, cả nữ thần lẫn cái tên đều được đọc là Lokkhi."},"arjun":{"vi":"Arjuna là người anh hùng bắn cung của sử thi Mahabharata — người thứ ba trong năm anh em Pandava, con của thần Indra, và là chiến binh mà Krishna truyền cho bài Bhagavad Gita trên chiến trường Kurukshetra. Từ tiếng Phạn arjuna nghĩa là “sáng, bạc, trắng”. Dưới dạng Arjun, đây là một trong những tên con trai được ưa chuộng nhất ở Ấn Độ ngày nay, và sử thi đã đưa nhân vật này lan khắp Đông Nam Á, nơi vị ksatriya tao nhã Arjuna (người Java gọi là Janaka) là nhân vật được yêu thích trong sân khấu bóng wayang."},"sita":{"vi":"Sita là nữ chính của sử thi Ramayana và là vợ của Rama, một hóa thân của Lakshmi và là hiện thân lý tưởng của đức hạnh, lòng tận tụy và sự thủy chung. Tên tiếng Phạn của bà nghĩa là “luống cày”: bà được vua Janaka tìm thấy trên một cánh đồng vừa cày, con gái của nữ thần đất Bhumi. Sử thi đã đưa bà lan khắp Đông Nam Á — bà là Nang Sida (นางสีดา) trong Ramakien của Thái Lan, Sinta hay Shinta trong wayang của người Java, và Neang Seda trong Reamker của Campuchia."},"ganesh":{"vi":"Ganesha là người con đầu voi của Shiva và Parvati, vị thần được yêu mến chuyên dẹp bỏ chướng ngại và là đấng bảo trợ của những khởi đầu, sự học và nghệ thuật, được khấn cầu trước mọi việc mới. Tên tiếng Phạn của ngài ghép gaṇa “đám, đoàn quân” với īśa “chúa tể”, và ngài cũng được biết đến với danh xưng Vinayaka và Ganapati. Dưới dạng Ganesh, đây là một tên con trai phổ biến ở Ấn Độ, và vị thần này lan khắp Đông Nam Á — được thờ ở Thái Lan là Phra Phikhanet (พระพิฆเนศ), đấng bảo trợ nghệ thuật, và ở Indonesia là Ganesha, mà hình ảnh của ngài là biểu tượng của Viện Công nghệ Bandung (ITB)."},"priya":{"vi":"Priya thuần túy là một tên gọi chứ không phải một vị thần — dạng giống cái của từ tiếng Phạn priya “yêu dấu, thân thương”, từ căn prī “làm vui lòng”. Đây là một trong những tên nữ phổ biến nhất thời nay khắp Ấn Độ, Nepal, Bangladesh và Sri Lanka, và dễ dàng theo chân cộng đồng di dân nhờ hình thức thân thiện, dễ phát âm. Trong tiếng Tamil, dạng giống đực Priyan hay Priya cũng được dùng cho nam giới. Căn từ này rất cổ xưa: nó cùng gốc với tên của nữ thần German Frigg, cả hai đều bắt nguồn từ tiếng Ấn-Âu nguyên thủy *priH- “được yêu”."}};
